import { useEffect, useState } from "react";
import { useParams, Link } from "react-router-dom";
import api from "@/lib/api";
import { Button } from "@/components/ui/button";
import { Truck, CheckCircle2, Package, ChefHat, Download, XCircle } from "lucide-react";

const STAGES = [
  { key: "placed", label: "Order Placed", icon: Package },
  { key: "confirmed", label: "Confirmed", icon: ChefHat },
  { key: "rider_assigned", label: "Rider Assigned", icon: Truck },
  { key: "delivered", label: "Delivered", icon: CheckCircle2 },
];

const formatDateTime = (value) => {
  if (!value) return "—";
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? "—" : date.toLocaleString();
};

export default function OrderDetail() {
  const { id } = useParams();
  const [o, setO] = useState(null);
  // useEffect(() => { api.get(`/orders/${id}`).then((r) => setO(r.data)); }, [id]);
  useEffect(() => {
    let interval;

    const fetchOrder = async () => {
      try {
        const res = await api.get(`/orders/${id}`);
        setO(res.data);
      } catch (err) {
        console.error(err);
      }
    };

    fetchOrder(); // Initial load

    interval = setInterval(fetchOrder, 5000); // Every 5 seconds

    return () => clearInterval(interval);
  }, [id]);
  if (!o) return <div className="py-20 text-center">Loading...</div>;
  const idx = STAGES.findIndex((s) => s.key === o.status);

  const invoice = () => {
    const cancellationNote = o.cancellation_reason ? `<p><b>Cancellation Reason:</b> ${o.cancellation_reason}</p>` : "";
    const html = `
<html><head><title>Invoice ${o.order_no}</title>
<style>body{font-family:Arial;padding:40px;max-width:700px;margin:auto;}h1{color:#D97706}table{width:100%;border-collapse:collapse}td,th{padding:8px;border-bottom:1px solid #eee;text-align:left}</style>
</head><body><h1>SLV Bakery</h1><p><b>Invoice:</b> ${o.order_no}<br/><b>Order Date:</b> ${formatDateTime(o.created_at)}<br/><b>Delivered Date:</b> ${o.status === "delivered" && o.delivered_at ? formatDateTime(o.delivered_at) : "—"}<br/><b>Status:</b> ${o.status}<br/><b>Customer:</b> ${o.user_name} (${o.user_email})<br/><b>Phone:</b> ${o.phone}<br/><b>Address:</b> ${o.address}</p>
${cancellationNote}
<table><thead><tr><th>Item</th><th>Qty</th><th>Price</th><th>Total</th></tr></thead><tbody>
${o.items.map(i => `<tr><td>${i.name}</td><td>${i.quantity}</td><td>₹${i.price}</td><td>₹${(i.price * i.quantity).toFixed(0)}</td></tr>`).join("")}
</tbody></table><br/>
<p>Subtotal: ₹${o.subtotal}<br/>Platform: ₹${o.platform_fee}<br/>Delivery: ₹${o.delivery_charge}<br/>Packaging: ₹${o.packaging}<br/>Discount: -₹${o.discount}<br/><b>Grand Total: ₹${o.total}</b></p>
<p>Payment: ${o.payment_method}</p></body></html>`;
    const w = window.open("", "_blank"); w.document.write(html); w.document.close(); w.print();
  };

  return (
    <div className="max-w-4xl mx-auto px-4 py-10" data-testid="order-detail">
      <div className="flex items-center justify-between mb-6 flex-wrap gap-3">
        <div>
          <div className="uppercase-tracked text-xs text-[#D97706]">Order</div>
          <h1 className="font-display text-2xl md:text-3xl font-bold">{o.order_no}</h1>
        </div>
        <div className="flex gap-2">
          <Button onClick={invoice} variant="outline" className="rounded-full" data-testid="download-invoice"><Download className="w-4 h-4 mr-1" /> Invoice</Button>
        </div>
      </div>
      <div className="bg-white border border-[#E6DFD5] rounded-2xl p-6 mb-4">
        <h3 className="font-semibold mb-4">Tracking</h3>

        {o.status === "cancelled" ? (
          <div className="flex flex-col items-center justify-center ">
            <div className="w-14 h-14 rounded-full bg-red-100 flex items-center justify-center">
              <XCircle className="w-8 h-8 text-red-600" />
            </div>

            <h4 className="mt-4 text-lg font-semibold text-red-600">
              Order Cancelled
            </h4>

            <p className="text-sm text-gray-500 mt-2 text-center">
              This order has been cancelled and will not be processed.
            </p>
          </div>
        ) : (
          <>
            <div className="grid grid-cols-4 gap-2">
              {STAGES.map((s, i) => {
                const active = i <= idx;
                const Icon = s.icon;

                return (
                  <div key={s.key} className="text-center">
                    <div
                      className={`w-10 h-10 mx-auto rounded-full flex items-center justify-center ${active
                          ? "bg-[#D97706] text-white"
                          : "bg-[#FBF5EA] text-[#5C4A3D]"
                        }`}
                    >
                      <Icon className="w-5 h-5" />
                    </div>

                    <div
                      className={`text-xs mt-2 ${active ? "font-semibold" : "text-[#5C4A3D]"
                        }`}
                    >
                      {s.label}
                    </div>
                  </div>
                );
              })}
            </div>

            {(o.rider_name || o.rider_phone) && (
              <div className="text-sm mt-4 text-center space-y-1">
                {o.rider_name && <div>Rider: <b>{o.rider_name}</b></div>}
                {o.rider_phone && <div>Rider Phone: <b>{o.rider_phone}</b></div>}
              </div>
            )}
          </>
        )}
      </div>
      <div className="bg-white border border-[#E6DFD5] rounded-2xl p-6">
        <h3 className="font-semibold mb-3">Items</h3>
        {o.items.map((i, k) => (
          <div key={k} className="flex justify-between text-sm py-1 border-b border-[#F3EEE4] last:border-0">
            <div>{i.name} x {i.quantity}</div>
            <div>₹{(i.price * i.quantity).toFixed(0)}</div>
          </div>
        ))}
        <div className="mt-4 text-sm space-y-1">
          <div className="flex justify-between"><span>Subtotal</span><span>₹{o.subtotal}</span></div>
          <div className="flex justify-between"><span>Platform Fee</span><span>₹{o.platform_fee}</span></div>
          <div className="flex justify-between"><span>Delivery</span><span>₹{o.delivery_charge}</span></div>
          <div className="flex justify-between"><span>Packaging</span><span>₹{o.packaging}</span></div>
          {o.discount > 0 && <div className="flex justify-between text-[#4D7C0F]"><span>Discount</span><span>-₹{o.discount}</span></div>}
          <div className="flex justify-between font-bold text-lg pt-2 border-t border-[#E6DFD5]"><span>Total</span><span>₹{o.total}</span></div>
        </div>
        <div className="mt-4 text-sm text-[#5C4A3D] space-y-1">
          <div>Ordered: {formatDateTime(o.created_at)}</div>
          {o.status === "delivered" && o.delivered_at && (
            <div>Delivered: {formatDateTime(o.delivered_at)}</div>
          )}
          {o.status === "cancelled" && o.cancellation_reason && (
            <div className="text-red-600">Cancellation reason: {o.cancellation_reason}</div>
          )}
          {o.rider_phone && <div>Rider Phone: {o.rider_phone}</div>}
          <div>Address: {o.address}</div>
          <div>Phone: {o.phone}</div>
          <div>Payment: {o.payment_method}</div>
        </div>
      </div>
      <div className="mt-4"><Link to="/my-orders" className="text-[#D97706] text-sm">← Back to orders</Link></div>
    </div>
  );
}
